function VerifyGL2Certificate(p, s, t):
    if det(s) mod p == 0: return REJECT      # s not invertible
    if det(t) mod p == 0: return REJECT      # t not invertible
    # charpoly of s is x^2 - tr(s) x + det(s)
    if exists r in F_p with r^2 - tr(s)*r + det(s) == 0:
        return REJECT                        # charpoly of s reducible
    Es <- { projective eigenvectors of s over F_p }   # empty if irreducible
    Et <- { projective eigenvectors of t over F_p }
    if Es intersect Et is nonempty: return REJECT     # common eigenvector
    return CERTIFIED

