function VertexExpansion(G, S):
    best <- +infinity
    for each size k from 1 to floor(|G| / 2):
        for each subset A of G with |A| = k:
            N <- { mul(a, s) : a in A, s in S }
            boundary <- N \ A
            best <- min(best, |boundary| / |A|)
    return best

